import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Module: op_registry","description":"","frontmatter":{},"headers":[],"relativePath":"api/host/handl_plugin_lib_handl/op_registry.md","filePath":"api/host/handl_plugin_lib_handl/op_registry.md"}`),a={name:`api/host/handl_plugin_lib_handl/op_registry.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<p><strong>handl_plugin_lib_handl &gt; op_registry</strong></p><h1 id="module-op-registry" tabindex="-1">Module: op_registry <a class="header-anchor" href="#module-op-registry" aria-label="Permalink to “Module: op_registry”">​</a></h1><h2 id="contents" tabindex="-1">Contents <a class="header-anchor" href="#contents" aria-label="Permalink to “Contents”">​</a></h2><p><strong>Structs</strong></p><ul><li><a href="#opfunction"><code>OpFunction</code></a> - A callable [<code>Function</code>] that dispatches to a Rust handl registered in an</li><li><a href="#opregistry"><code>OpRegistry</code></a> - A thread-safe registry mapping op names to Rust <code>Function</code> impls (the</li></ul><p><strong>Traits</strong></p><ul><li><a href="#runtimepredicatechecker"><code>RuntimePredicateChecker</code></a> - A runtime checker for op axiom predicates (ADR-0077 Phase 3).</li></ul><hr><h2 id="handl-plugin-lib-handl-op-registry-opfunction" tabindex="-1">handl_plugin_lib_handl::op_registry::OpFunction <a class="header-anchor" href="#handl-plugin-lib-handl-op-registry-opfunction" aria-label="Permalink to “handl_plugin_lib_handl::op_registry::OpFunction”">​</a></h2><p><em>Struct</em></p><p>A callable [<code>Function</code>] that dispatches to a Rust handl registered in an [<code>OpRegistry</code>].</p><p>This is the eval-time bridge between the <code>op</code>/<code>handl</code> declaration form (ADR-0077 Phase 2) and the existing <code>ModuleLookup</code> dispatch. When a <code>.hnl</code> file declares <code>op &quot;base64.encode&quot;</code> and <code>handl &quot;base64.encode&quot; = rust_base64_encode</code>, the loaded <a href="crate::HandlModule" target="_blank" rel="noreferrer"><code>HandlModule</code></a> creates an <code>OpFunction</code> for each op. The <code>OpFunction</code> holds the op name and a shared <code>Arc&lt;OpRegistry&gt;</code>; on call, it looks up the op name in the registry and dispatches to the registered Rust <code>Function</code>.</p><p>This plugs into the existing eval engine without changes: the <code>OpFunction</code> is a regular <code>Function</code> stored in a <code>Module</code>, looked up via <code>ModuleLookup::lookup(name)</code>.</p><p><strong>Fields:</strong></p><ul><li><code>op_name: String</code> - The op name (e.g. <code>&quot;base64.encode&quot;</code>).</li><li><code>registry: std::sync::Arc&lt;OpRegistry&gt;</code> - The shared op registry.</li></ul><p><strong>Methods:</strong></p><ul><li><code>fn new&lt;impl Into&lt;String&gt;&gt;(op_name: impl Trait, registry: Arc&lt;OpRegistry&gt;) -&gt; Self</code> - Create a new <code>OpFunction</code> for the given op name and registry.</li></ul><p><strong>Trait Implementations:</strong></p><ul><li><strong>Function</strong><ul><li><code>fn call(self: &amp;Self, args: &amp;[Value], ctx: &amp; mut EvalContext) -&gt; Result&lt;Value, EvalError&gt;</code></li></ul></li><li><strong>Clone</strong><ul><li><code>fn clone(self: &amp;Self) -&gt; Self</code></li></ul></li></ul><h2 id="handl-plugin-lib-handl-op-registry-opregistry" tabindex="-1">handl_plugin_lib_handl::op_registry::OpRegistry <a class="header-anchor" href="#handl-plugin-lib-handl-op-registry-opregistry" aria-label="Permalink to “handl_plugin_lib_handl::op_registry::OpRegistry”">​</a></h2><p><em>Struct</em></p><p>A thread-safe registry mapping op names to Rust <code>Function</code> impls (the handls), with optional runtime axiom checkers (ADR-0077 Phase 3).</p><p>This is the host-side counterpart to the <code>op</code>/<code>handl</code> declaration form (ADR-0077 Phase 2). A <code>.hnl</code> file declares <code>op &quot;base64.encode&quot; : String -&gt; String</code> and <code>handl &quot;base64.encode&quot; = rust_base64_encode</code>; the host crate registers a Rust <code>Function</code> impl under the op name <code>&quot;base64.encode&quot;</code> via this registry. At eval time, [<code>OpFunction</code>] looks up the op name in the registry and dispatches to the registered <code>Function</code>.</p><p>In addition (ADR-0077 Phase 3), a [<code>RuntimePredicateChecker</code>] may be attached to an op via [<code>OpRegistry::register_with_checker</code>]. When present, [<code>OpFunction::call</code>] enforces the op&#39;s <code>requires</code>/<code>guarantee</code> axioms at the dispatch boundary: <code>requires</code> is checked before the call, <code>guarantee</code> is checked against the return value after the call.</p><p>The registry is <code>Send + Sync</code> and uses interior mutability only at construction time (via <code>&amp;mut self</code> on [<code>OpRegistry::register</code>]). Once built, it is shared immutably via <code>Arc&lt;OpRegistry&gt;</code>.</p><p><strong>Fields:</strong></p><ul><li><code>ops: std::collections::HashMap&lt;String, std::sync::Arc&lt;dyn Function&gt;&gt;</code> - Op name → Rust <code>Function</code> impl (the handl).</li><li><code>checkers: std::collections::HashMap&lt;String, std::sync::Arc&lt;dyn RuntimePredicateChecker&gt;&gt;</code> - Op name → optional runtime axiom checker.</li></ul><p><strong>Methods:</strong></p><ul><li><code>fn new() -&gt; Self</code> - Create a new, empty <code>OpRegistry</code>.</li><li><code>fn register(self: &amp; mut Self, op_name: &amp;str, func: Arc&lt;dyn Function&gt;)</code> - Register a Rust <code>Function</code> impl (the handl) under an op name.</li><li><code>fn register_with_checker(self: &amp; mut Self, op_name: &amp;str, func: Arc&lt;dyn Function&gt;, checker: Option&lt;Arc&lt;dyn RuntimePredicateChecker&gt;&gt;)</code> - Register a Rust <code>Function</code> impl (the handl) under an op name, with an</li><li><code>fn get(self: &amp;Self, op_name: &amp;str) -&gt; Option&lt;Arc&lt;dyn Function&gt;&gt;</code> - Look up the <code>Function</code> impl registered under an op name.</li><li><code>fn get_checker(self: &amp;Self, op_name: &amp;str) -&gt; Option&lt;Arc&lt;dyn RuntimePredicateChecker&gt;&gt;</code> - Look up the runtime axiom checker for an op, if any (ADR-0077 Phase 3).</li><li><code>fn contains(self: &amp;Self, op_name: &amp;str) -&gt; bool</code> - Returns <code>true</code> if an op with the given name is registered.</li><li><code>fn len(self: &amp;Self) -&gt; usize</code> - Returns the number of registered ops.</li><li><code>fn is_empty(self: &amp;Self) -&gt; bool</code> - Returns <code>true</code> if no ops are registered.</li></ul><p><strong>Trait Implementations:</strong></p><ul><li><strong>Default</strong><ul><li><code>fn default() -&gt; Self</code></li></ul></li></ul><h2 id="handl-plugin-lib-handl-op-registry-runtimepredicatechecker" tabindex="-1">handl_plugin_lib_handl::op_registry::RuntimePredicateChecker <a class="header-anchor" href="#handl-plugin-lib-handl-op-registry-runtimepredicatechecker" aria-label="Permalink to “handl_plugin_lib_handl::op_registry::RuntimePredicateChecker”">​</a></h2><p><em>Trait</em></p><p>A runtime checker for op axiom predicates (ADR-0077 Phase 3).</p><p>Op authors can optionally provide a checker when registering an op. If provided, the checker is called at eval time by [<code>OpFunction::call</code>]:</p><ul><li>[<code>RuntimePredicateChecker::check_requires</code>] is called <strong>before</strong> the op executes, with the call args. If it returns <code>Err</code>, the call is rejected.</li><li>[<code>RuntimePredicateChecker::check_guarantee</code>] is called <strong>after</strong> the op executes, with the return value. If it returns <code>Err</code>, the result is rejected.</li></ul><p>If no checker is registered for an op, its axioms are <strong>trusted</strong> (no runtime check is performed) — the op behaves exactly as before.</p><p>The checker is <code>Send + Sync</code> so it can be shared across threads via [<code>Arc</code>] alongside the [<code>OpRegistry</code>].</p><p><strong>Methods:</strong></p><ul><li><code>check_requires</code>: Check the <code>requires</code> predicate against call arguments.</li><li><code>check_guarantee</code>: Check the <code>guarantee</code> predicate against the return value.</li></ul>`,40)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};